function ghlGet(path) {
  return new Promise((ok, fail) => {
    https.get({ hostname: BASE, path, headers: { Authorization: `Bearer ${TOKEN}`, Version: '2023-02-21' } }, r => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => {
        try { ok(JSON.parse(d)); } catch (e) { ok({ _raw: d }); }
      });
    }).on('error', fail);
  });
}

function ghlPatch(path, body) {
  return new Promise((ok, fail) => {
    const data = JSON.stringify(body);
    const opts = { hostname: BASE, path, method: 'PUT', headers: { Authorization: `Bearer ${TOKEN}`, Version: '2023-02-21', 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } };
    const req = https.request(opts, r => { let d = ''; r.on('data', c => d += c); r.on('end', () => { try { ok(JSON.parse(d)); } catch (e) { ok({ _raw: d }); } }); });
    req.on('error', fail);
    req.write(data);
    req.end();
  });
}

function ghlPost(path, body) {
  return new Promise((ok, fail) => {
    const data = JSON.stringify(body);
    const opts = { hostname: BASE, path, method: 'POST', headers: { Authorization: `Bearer ${TOKEN}`, Version: '2023-02-21', 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } };
    const req = https.request(opts, r => { let d = ''; r.on('data', c => d += c); r.on('end', () => { try { ok(JSON.parse(d)); } catch (e) { ok({ _raw: d }); } }); });
    req.on('error', fail);
    req.write(data);
    req.end();
  });
}

async function fetchOpportunity(oppId) {
  const res = await ghlGet(`/opportunities/${oppId}`);
  return res.opportunity || res;
}

async function fetchContactNotes(oppId) {
  // V2 API: notes live on the contact, not the opportunity. The opp search
  // endpoint doesn't include notes inline, so we fetch the opp to get
  // contactId, then the contact's notes endpoint. Return concatenated body
  // text so the stage handlers can use `notes.includes('BUY BOX')` etc.
  const opp = await fetchOpportunity(oppId);
  const contactId = opp.contactId || opp.contact?.id;
  if (!contactId) return '';
  assertOurPipeline(opp);
  const res = await ghlGet(`/contacts/${contactId}/notes/`);
  const notes = res.notes || [];
  return notes.map(n => n.body || '').join('\n');
}

async function fetchContactConversationMessages(oppId, limit = 50) {
  const opp = await fetchOpportunity(oppId);
  const contactId = opp.contactId || opp.contact?.id;
  if (!contactId) return [];
  assertOurPipeline(opp);

  const search = await ghlGet(`/conversations/search?locationId=${LOCATION_ID}&contactId=${encodeURIComponent(contactId)}&limit=20`);
  const conversations = Array.isArray(search.conversations) ? search.conversations : [];
  const messages = [];

  for (const conversation of conversations) {
    if (!conversation.id) continue;
    const res = await ghlGet(`/conversations/${conversation.id}/messages?limit=${limit}`);
    const raw = res.messages?.messages || res.messages || res.conversationMessages || res.data || [];
    if (!Array.isArray(raw)) continue;
    for (const message of raw) {
      messages.push({
        conversationId: conversation.id,
        conversationType: conversation.type,
        contactId,
        id: message.id,
        type: message.type,
        direction: message.direction,
        status: message.status,
        source: message.source,
        dateAdded: message.dateAdded || message.createdAt,
        body: message.body || message.message || message.text || '',
        attachments: message.attachments || [],
        meta: message.meta || {},
      });
    }
  }

  messages.sort((a, b) => String(a.dateAdded || '').localeCompare(String(b.dateAdded || '')));
  return messages;
}

async function updateOpportunityNotes(oppId, notes) {
  return ghlPatch(`/opportunities/${oppId}`, { notes });
}

async function updateOpportunityStage(oppId, stageId) {
  return ghlPatch(`/opportunities/${oppId}`, { pipelineStageId: stageId });
}

