// =============================================================
// recommendStrategy() ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â Exit Strategy Cheatsheet logic
// Added 2026-06-04 per Missing Files Audit
// Source: Pay Per Click (PPC)/Exit Strategy Cheatsheet.docx
// =============================================================
//
// Decision tree from Kay's actual cheatsheet:
//   Cash         -> High motivation
//   Subject To   -> Low equity AND low interest rate
//   Stack 50%    -> Equity over 50% AND move-in ready house
//   Stack 10%    -> Equity over 90% AND a flip (needs renovation)
//   Novation     -> Move-in ready house with no motivation (no timeline)
//   $0 Down      -> Rental AND owned outright / free and clear

const EXIT_STRATEGY_RULES = {
  'Cash': {
    name: 'Cash Offer',
    condition: 'High motivation (seller wants out fast)',
    contractType: 'Cash',
    template: 'CashOffer'
  },
  'SubjectTo': {
    name: 'Subject-To',
    condition: 'Low equity AND low interest rate',
    contractType: 'SubTo',
    template: 'PSACreativeSubTo'
  },
  'Stack50': {
    name: 'Stack 50% Down',
    condition: 'Equity over 50% AND move-in ready house',
    contractType: 'Stack',
    template: 'Stack5yrBAL'
  },
  'Stack10': {
    name: 'Stack 10% Down',
    condition: 'Equity over 90% AND a flip (needs renovation)',
    contractType: 'Stack',
    template: 'Ai10DPBalloon'
  },
  'Novation': {
    name: 'Novation',
    condition: 'Move-in ready house with no motivation (no timeline to sell)',
    contractType: 'Commercial',
    template: 'PSACommercial'
  },
  'ZeroDown': {
    name: '$0 Down',
    condition: 'Rental AND owned outright / free and clear (no mortgage)',
    contractType: 'SubTo',
    template: 'ZeroDown'
  }
};

function recommendStrategy(property) {
  const {
    motivation,         // 'high' | 'medium' | 'low' | 'none'
    equityPercent,      // 0-100
    interestRate,       // current rate, e.g. 0.07
    isRental,           // boolean
    isOwnedFree,        // boolean (no mortgage)
    needsRenovation,    // boolean
    moveInReady         // boolean
  } = property;

  // Apply rules in priority order
  if (motivation === 'high') {
    return { strategy: 'Cash', ...EXIT_STRATEGY_RULES.Cash };
  }

  if (isRental && isOwnedFree) {
    return { strategy: 'ZeroDown', ...EXIT_STRATEGY_RULES.ZeroDown };
  }

  if (equityPercent < 50 && interestRate && interestRate < 0.06) {
    return { strategy: 'SubjectTo', ...EXIT_STRATEGY_RULES.SubjectTo };
  }

  if (equityPercent > 90 && needsRenovation) {
    return { strategy: 'Stack10', ...EXIT_STRATEGY_RULES.Stack10 };
  }

  if (equityPercent > 50 && moveInReady) {
    return { strategy: 'Stack50', ...EXIT_STRATEGY_RULES.Stack50 };
  }

  if (moveInReady && (motivation === 'none' || motivation === 'low')) {
    return { strategy: 'Novation', ...EXIT_STRATEGY_RULES.Novation };
  }

  // Default: Stack 50% if no other match
  return {
    strategy: 'Stack50',
    ...EXIT_STRATEGY_RULES.Stack50,
    fallback: true,
    note: 'No specific rule matched; defaulting to Stack 50%'
  };
}
// =============================================================
// MID-TERM PIVOT (added 2026-06-04)
// =============================================================
// When long-term rental doesn't pass the 1% rule, pivot to mid-term
// rental comps via Furnished Finder (per-room rate Ã— bedroom count).
//
// Source: video 03 (Calc + Dispo walkthrough)
// Example: 8 E Tunbridge Ct, Johnson City TN â€” long-term rent below
// 1% rule, but Furnished Finder shows $1,500/room Ã— 3 rooms = $4,500/mo
// which is well above 1% on a $210K purchase.

function midTermPivot({
  askingPrice,
  longTermRent,
  zipCode,
  neighborhood,
  bedrooms,
  perRoomRate,         // optional: if user already pulled from Furnished Finder
  city
} = {}) {
  // 1% rule check on long-term
  const onePercent = askingPrice * 0.01;
  const longTermPasses = longTermRent >= onePercent;
  const longTermGap = longTermRent - onePercent;

  if (longTermPasses) {
    return {
      pivot: false,
      reason: 'Long-term rental already passes 1% rule. No mid-term pivot needed.',
      longTermRent,
      onePercentThreshold: onePercent
    };
  }

  // Calculate mid-term estimate
  // Default per-room rate: $1,500 (per video 03 example)
  // If user provided actual per-room rate, use that
  const perRoom = perRoomRate || 1500;
  const midTermEstimate = bedrooms ? perRoom * bedrooms : null;
  const midTermOnePercent = midTermEstimate ? (midTermEstimate / (askingPrice / 100)) : null;

  return {
    pivot: true,
    reason: 'Long-term rental below 1% rule. Pivoting to mid-term via Furnished Finder.',
    longTerm: {
      rent: longTermRent,
      threshold: onePercent,
      gap: longTermGap,
      passes: false
    },
    midTerm: {
      perRoomRate: perRoom,
      bedrooms,
      estimatedMonthlyRent: midTermEstimate,
      onePercentRule: midTermOnePercent ? midTermOnePercent.toFixed(2) + '%' : null,
      passes: midTermEstimate ? midTermEstimate >= onePercent : false,
      lookupInstructions: [
        `1. Go to Furnished Finder: https://www.furnishedfinder.com/`,
        `2. Search zip: ${zipCode || 'n/a'}`,
        `3. Filter by neighborhood: ${neighborhood || city || 'n/a'}`,
        `4. NOTE: Furnished Finder is BY THE ROOM (not whole property)`,
        `5. Take the LOWEST 1BR rate Ã— ${bedrooms || '?'} rooms = total monthly rent`,
        `6. Update perRoomRate here to refine the estimate`,
        perRoom ? null : `7. Default per-room rate used: $${perRoom} (from video 03 example â€” verify with actual lookup)`
      ].filter(Boolean)
    }
  };
}


// =============================================================
// PIPELINE SAFETY (added 2026-06-04 per Montelli directive)
// WHY: Original pipeline is used by 30+ existing students with
// active deals. We built our own (nSf3NXYVkt8X4PgW9aZ3, named
// 'Montelli') so we can build/break without harming them.
// Refuses ANY write to a pipeline other than our NEW automation.
// Kayla's original (ygQaJ2hi7ouJeA5HR7uu) and Deal Closing
// (sEkQjhT34Lz5qd05jxmD) are READ-ONLY for us.
// =============================================================
const ALLOWED_PIPELINE_ID = PIPELINE_ID;  // nSf3NXYVkt8X4PgW9aZ3
const FORBIDDEN_PIPELINES = new Set([
  'ygQaJ2hi7ouJeA5HR7uu',   // Kayla's original
  'sEkQjhT34Lz5qd05jxmD',   // Deal closing
]);

function assertOurPipeline(opp) {
  if (!opp || !opp.pipelineId) {
    throw new Error('SAFETY: opportunity missing pipelineId');
  }
  if (FORBIDDEN_PIPELINES.has(opp.pipelineId)) {
    throw new Error(
      'SAFETY REFUSED: Cannot modify opportunity in pipeline ' + opp.pipelineId +
      ' (Kayla/Rose pipeline). Atlas only writes to ' + ALLOWED_PIPELINE_ID + '.'
    );
  }
  if (opp.pipelineId !== ALLOWED_PIPELINE_ID) {
    throw new Error(
      'SAFETY REFUSED: Unknown pipeline ' + opp.pipelineId + '. ' +
      'Atlas only writes to ' + ALLOWED_PIPELINE_ID + '.'
    );
  }
  return true;
}

async function safePatchOpportunity(opportunityId, body) {
  const opp = await fetchOpportunity(opportunityId);
  assertOurPipeline(opp);
  return ghlPatch('/opportunities/' + opportunityId, body);
}

async function safeUpdateNotes(opportunityId, notes) {
  // V2 API: notes are on contacts, not opportunities
  const opp = await fetchOpportunity(opportunityId);
  assertOurPipeline(opp);
  const contactId = opp.contactId || opp.contact?.id;
  if (!contactId) {
    throw new Error(`SAFETY: opportunity ${opportunityId} has no contactId`);
  }
  return ghlPost(`/contacts/${contactId}/notes`, { body: notes });
}

async function safeUpdateStage(opportunityId, stageId) {
  return safePatchOpportunity(opportunityId, { pipelineStageId: stageId });
}

// ─── runAllStrategies wrapper (Montelli 6/5 spec) ───────────────────────
// Wraps cash-offer-underwriter.runAllStrategies() with course-aligned defaults
// and returns all 5 strategies side-by-side for Stage 3 → Stage 4 auto-move.
const cashUnderwriter = require('./cash-offer-underwriter.js');

async function runAllStrategies(opportunityId, fields) {
  if (!opportunityId) throw new Error('runAllStrategies requires opportunityId');
  if (!fields || typeof fields !== 'object') throw new Error('runAllStrategies requires fields object');
  const opp = await fetchOpportunity(opportunityId);
  assertOurPipeline(opp);

  const aru = Number(fields.lowest_aru_comp);
  const tier = Number(fields.repair_tier);
  const sqft = Number(fields.repair_sqft);
  const fee = (fields.wholesale_fee !== undefined && fields.wholesale_fee !== null)
    ? Number(fields.wholesale_fee) : cashUnderwriter.WHOLESALE_FEE_DEFAULT;

  if (!aru || !sqft) {
    throw new Error('Missing required fields: lowest_aru_comp and repair_sqft are required');
  }
  if (![30, 45, 60].includes(tier)) {
    throw new Error('repair_tier must be 30, 45, or 60');
  }

  const result = cashUnderwriter.runAllStrategies({
    aru,
    tier,
    sqft,
    fee,
    existingLoan: fields.existing_loan_balance ? Number(fields.existing_loan_balance) : 0,
    existingRate: fields.existing_loan_rate ? Number(fields.existing_loan_rate) : 0,
    address: opp.address || opp.name || null,
  });
  return result;
}

/**
 * runAllStrategiesLocal(fields)
 * Pure-math runAllStrategies with no GHL fetch — used by /offer chat command
 * when there's no real opportunity in the pipeline yet (what-if runs).
 *
 * Required: aru (lowest_aru_comp), tier (repair_tier: 30/45/60), sqft (repair_sqft)
 * Optional: fee (default WHOLESALE_FEE_DEFAULT), existingLoan, existingRate, address
 */
function runAllStrategiesLocal(fields) {
  if (!fields || typeof fields !== 'object') throw new Error('runAllStrategiesLocal requires fields object');
  const aru = Number(fields.lowest_aru_comp || fields.aru);
  const tier = Number(fields.repair_tier || fields.tier);
  const sqft = Number(fields.repair_sqft || fields.sqft);
  const fee = (fields.wholesale_fee !== undefined && fields.wholesale_fee !== null)
    ? Number(fields.wholesale_fee)
    : (fields.fee !== undefined ? Number(fields.fee) : cashUnderwriter.WHOLESALE_FEE_DEFAULT);

  if (!aru || !sqft) {
    throw new Error('Missing required fields: lowest_aru_comp (aru) and repair_sqft (sqft) are required');
  }
  if (![30, 45, 60].includes(tier)) {
    throw new Error('repair_tier (tier) must be 30, 45, or 60');
  }

  return cashUnderwriter.runAllStrategies({
    aru, tier, sqft, fee,
    existingLoan: fields.existing_loan_balance ? Number(fields.existing_loan_balance) : 0,
    existingRate: fields.existing_loan_rate ? Number(fields.existing_loan_rate) : 0,
    address: fields.address || null,
  });
}

// formatAllStrategies() — converts the runAllStrategies() result to a GHL-note-ready string
function formatAllStrategies(result) {
  if (!result || !result.cash) throw new Error('formatAllStrategies requires runAllStrategies() result');
  const m = result.meta;
  const lines = [
    '=== CASH OFFER UNDERWRITING (Course Applicability Engine) ===',
    `ARV: $${m.aru.toLocaleString()} | Repair tier: $${m.tier}/sqft | Sqft: ${m.sqft.toLocaleString()} | Repairs: $${m.repairs.toLocaleString()}`,
    `Wholesale fee: $${m.fee.toLocaleString()} (OWNER: $${m.feeOwner?.toLocaleString()}, COURSE: $${m.feeCourse?.toLocaleString()})`,
    '',
    'STRATEGY         | OFFER       | SOURCE       | STRUCTURE',
    '─────────────────┼─────────────┼──────────────┼──────────────────────────────────',
    `Cash             | $${result.cash.offer.toLocaleString().padStart(10)} | ${result.cash.source.padEnd(12)} | 0.70×ARV − repairs − fee`,
    `F50 (turnkey)    | $${result.f50.offer.toLocaleString().padStart(10)} | ${result.f50.source.padEnd(12)} | $${result.f50.downPayment.toLocaleString()} now + $${result.f50.carryback.toLocaleString()} in 72mo`,
    `F10 (renovation) | $${result.f10.offer.toLocaleString().padStart(10)} | ${result.f10.source.padEnd(12)} | $${result.f10.downPayment.toLocaleString()} now + $${result.f10.carryback.toLocaleString()} in 24mo`,
  ];

  if (result.subTo) {
    lines.push(`SubTo            | $${result.subTo.offer.toLocaleString().padStart(10)} | ${result.subTo.source.padEnd(12)} | Purchase − DP − EMD − Payoff = equity`);
    lines.push(`                 |              |              | Cash flow: $${result.subTo.monthlyCashFlow.toLocaleString()}/mo`);
  }

  if (result.rental) {
    const r = result.rental;
    lines.push(`Rental (LT)      | $${r.monthlyCashFlow.toLocaleString().padStart(10)} | ${r.source.padEnd(12)} | $${r.monthlyRent.toLocaleString()}/mo, 1%: ${r.onePercentPasses ? 'PASS' : 'FAIL'}`);
    lines.push(`                 |              |              | Cash flow: $${r.monthlyCashFlow.toLocaleString()}/mo (threshold: $${r.cashFlowThreshold})`);
    if (r.dscr !== null) lines.push(`                 |              |              | DSCR: ${r.dscr} (threshold: ${r.dscrThreshold})`);
  }

  if (result.midTerm) {
    const mt = result.midTerm;
    lines.push(`Mid-term (MTR)   | $${mt.offer.toLocaleString().padStart(10)} | ${mt.rentSource.padEnd(12)} | $${mt.monthlyRent.toLocaleString()}/mo`);
    lines.push(`                 |              |              | Cash flow threshold: $${mt.cashFlowThreshold} (MTR)`);
  }

  lines.push('');
  lines.push('Seller protections by strategy:');
  if (result.cash.sellerProtections.length) lines.push(`  Cash: ${result.cash.sellerProtections.join(', ')}`);
  if (result.f50.sellerProtections.length) lines.push(`  F50: ${result.f50.sellerProtections.join(', ')}`);
  if (result.f10.sellerProtections.length) lines.push(`  F10: ${result.f10.sellerProtections.join(', ')}`);
  if (result.subTo.sellerProtections.length) lines.push(`  SubTo: ${result.subTo.sellerProtections.join(', ')}`);

  lines.push('');
  lines.push('SOURCE LEGEND:');
  lines.push('  COURSE_UNIVERSAL — applies to all deals of this type');
  lines.push('  COURSE_PATH_SPECIFIC — applies to this strategy path');
  lines.push('  SPREADSHEET_EXAMPLE — deal-specific, not universal');
  lines.push('  OWNER_MODIFICATION — owner override from course default');
  lines.push('  ADVISORY_ESTIMATE — not verified, actual data required');
  lines.push('');
  lines.push('Recommended: pick the strategy that matches seller intent.');

  return lines.join('\n');
}

// handleOfferCalculated() — full auto-move flow:
// 1. Reads 4 custom fields from opportunity
// 2. Calls runAllStrategies()
// 3. Writes formatted multi-strategy note
// 4. Auto-moves Stage 3 → Stage 4
// 5. Triggers workflow 8e61cf9c (48hr timer)
async function handleOfferCalculated(opportunityId, fields) {
  const result = await runAllStrategies(opportunityId, fields);
  const note = formatAllStrategies(result);
  await safeUpdateNotes(opportunityId, note);
  // Auto-move Stage 3 (OFFER_READY) → Stage 4 (OFFER_SENT) per course file 17A + REI_STAGE_BY_STAGE_GUIDE
  await safeUpdateStage(opportunityId, STAGE.OFFER_SENT);
  return { result, note, stage: 'OFFER_SENT' };
}

module.exports = { calculate, formatOutput, run, fetchOpportunity, fetchContactNotes, fetchContactConversationMessages, updateOpportunityNotes, updateOpportunityStage, safePatchOpportunity, safeUpdateNotes, safeUpdateStage, assertOurPipeline, recommendStrategy, midTermPivot, runAllStrategies, runAllStrategiesLocal, formatAllStrategies, handleOfferCalculated, EXIT_STRATEGY_RULES, STAGE, PIPELINE_ID, LOCATION_ID };
